        'data': [
          _entryJson(
            id: 'entry-january',
            content: 'Registro de janeiro.',
            source: 'manual',
            occurredAt: '2026-01-15T10:00:00Z',
          ),
        ],
        'meta': {'nextCursor': null},
      });

      final dateFrom = DateTime(2026, 1, 1);
      final dateTo = DateTime(2026, 1, 31);
      final cubit = sl<MeusRegistrosCubit>();
